    ])
    Object.defineProperty(navigator, 'clipboard', {
      value: clipboard,
      writable: true
    })

    // "copied!" disappears after a while
    assert.equal(screen.getByTestId('copy-replay').textContent, 'copied!')

    await new Promise(resolve => {
